const assert = require('node:assert/strict');
const { total } = require('./total.cjs');
test('empty and nullable totals', () => {
  assert.equal(total([]), 0);
  assert.equal(total([null, undefined]), 0);
  assert.equal(total([0, -2, 3]), 1);
});

